    import com.auth0.jwt.interfaces.DecodedJWT;

    public String toString(DecodedJWT jwt) {
        StringBuilder buff = new StringBuilder();
        buff.append("\ntoken: " + jwt.getToken());
        buff.append("\n\nheader: " + new String(Base64Util.decode(jwt.getHeader())));
        buff.append("\n\npayload: " + new String(Base64Util.decode(jwt.getPayload())));
        // buff.append("\n\nsignature: " + new String(Base64Util.decode(jwt.getSignature())));
        buff.append("\n\nsignature: " + new String(java.util.Base64.getUrlDecoder().decode(jwt.getSignature())));

        return buff.toString();
    }

